  function releaseTransferPause(){if(ui.pauseReason==='game_running'&&ui.suspendedTransferStage){ui.stage=ui.suspendedTransferStage;ui.pauseReason=null;ui.suspendedTransferStage=null;}}
  function returnLobby(){ui.running=false;ui.launching=false;ui.runningGame=null;releaseTransferPause();const origin=ui.returnOrigin||{screen:'S07',variant:'default',selected:ui.selected};ui.screen=origin.screen;ui.variant=origin.variant;ui.selected=origin.selected;ui.history=[];ui.returnOrigin=null;updateHash();render();}
  function notify(message){ui.toast=message;render();document.getElementById('review-status').textContent=message;}
  function advance(){if(ui.launching){ui.launching=false;ui.running=true;ui.runningGame=ui.selected;if(ui.selected!=='space'&&['downloading','queued','verifying','preparing'].includes(ui.stage)){ui.suspendedTransferStage=ui.stage;ui.stage='paused';ui.pauseReason='game_running';}go('S09',{history:false});return;}const transitions={queued:'downloading',downloading:'verifying',paused:'downloading',wifi:'downloading',failed:'downloading',verifying:'preparing',preparing:'ready'};if(!transitions[ui.stage]){document.getElementById('review-status').textContent='当前没有需要推进的任务。';return;}ui.stage=transitions[ui.stage];ui.progress=['verifying','preparing','ready'].includes(ui.stage)?100:64;if(['verifying','preparing','ready'].includes(ui.stage)){ui.selected='space';go('S06',{variant:ui.stage==='ready'?'ready':ui.stage==='preparing'?'extracting':'verifying',history:false});}else render();}
