  function applyVariant(id,v){releaseTransferPause();ui.screen=id;ui.variant=v;ui.toast='';ui.modal=null;ui.history=[];ui.formError=false;ui.launching=false;if(id==='S03'){ui.selected=v==='installed'?'valley':'space';if(v!=='installed')ui.stage=v==='downloading'?'downloading':'absent';}if(id==='S04'){ui.selected='space';ui.stage='absent';ui.mobileConsent=false;}if(id==='S05'){ui.stage=({default:'downloading',paused:'paused',wifi:'wifi',failed:'failed',empty:'absent'})[v]||'downloading';ui.progress=64;}if(id==='S06'){ui.selected='space';ui.stage=({verifying:'verifying',extracting:'preparing',ready:'ready',failed:'verifying'})[v]||'verifying';ui.progress=100;}if(['S08','S09','S10','S11','S12','S13','S15','S16','S17','S26','S30','S31'].includes(id))ui.selected='valley';if(['S09','S10','S11'].includes(id)){ui.running=true;ui.runningGame=ui.selected;}else if(v==='running')ui.running=true;else ui.running=false;if(id==='S08')ui.launching=v!=='failed';if(id==='S07'){ui.selected='valley';ui.stage='downloading';ui.progress=64;}if(id==='S02')ui.query=v==='empty'?'未找到的游戏':'';if(id==='S21')ui.formError=v==='invalid';updateHash();render();}
