  device.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;actions[el.dataset.action]?.(el);});
  device.addEventListener('input',event=>{if(event.target.id==='feedback-text')ui.feedback=event.target.value;if(event.target.id==='feedback-contact')ui.contact=event.target.value;if(event.target.id==='game-search')ui.query=event.target.value;});
  device.addEventListener('change',event=>{if(event.target.id==='mobile-consent'){ui.mobileConsent=event.target.checked;render();}if(event.target.dataset.pref)ui.prefs[event.target.dataset.pref]=event.target.checked;});
  device.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.id==='game-search'){event.preventDefault();actions['submit-search']();}if(event.key==='Escape'){event.preventDefault();back();}const dialog=device.querySelector('[role=dialog]');if(dialog&&event.key==='Tab'){const controls=[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')];if(!controls.length)return;const first=controls[0],last=controls.at(-1);if(event.shiftKey&&(document.activeElement===first||!controls.includes(document.activeElement))){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
  let lastGroup='';document.getElementById('screen-list').innerHTML=pages.map(p=>{const heading=p.group!==lastGroup?`<h3>${p.group}</h3>`:'';lastGroup=p.group;return heading+`<button type="button" data-screen="${p.id}"><span>${p.id}</span>${p.title}</button>`;}).join('');
