  document.querySelectorAll('[data-review]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.review==='advance')advance();else if(button.dataset.review==='crash'){ui.running=false;ui.launching=false;ui.runningGame=null;releaseTransferPause();go('S12',{history:false});}else setScenario(button.dataset.review);}));
